using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitSenderEvidenceTests
{
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:unit-held/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds);
    static WorldSession Failed(bool known=true,bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=policy?NewGameMilitary.UnitCommandHoldingContract:null},s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().Delivered);if(known)At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    static WorldSession HomeReady(){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(ArmyEnd(s),j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static TroopDispatch Query(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();
    static TroopReceipt Answer(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();
    static UnitPostInquiryAnswer Quote(ContractWorld w){var r=w.NewMilitary!.UnitInquiry!.Receipts.Last();return ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body));}
    static void Ask(WorldSession s,NewMilitaryAction action=NewMilitaryAction.InquireUnitKnown,bool policy=true){var r=s.DecideNewMilitary(Input(s,action) with{PostPolicy=policy?NewGameMilitary.UnitReplyRecoveryContract:null,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void MoveAway(WorldSession s){var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+5000,home.Y)},s.PlayerControl,s.Revision).Code);}
    static WorldSession FailedReply(bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Ask(s,policy:policy);At(s,Query(s).DueAt);MoveAway(s);At(s,Answer(s).ReplyDueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Replies.Last().Received);return s;}
    static void AtPersonEnd(WorldSession s){var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);}
    static void WalkTo(WorldSession s,FieldPoint p){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=p},s.PlayerControl,s.Revision).Code);AtPersonEnd(s);}
    static WorldSession AtHeldOriginal(bool retryFirst=false){var s=FailedReply();var report=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single();if(retryFirst)Send(s,NewMilitaryAction.PersonalHome);At(s,report.DueAt);if(retryFirst)At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Last().DueAt);WalkTo(s,Query(s).Destination);return s;}
    static WorldSession AtMissedReport(){var s=HomeReady();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+5000,a.Y),B=new(a.X+5000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);long start=s.Seconds;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);var w=s.DiagnosticSnapshot();var known=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(NewGameMilitary.PersonPosition(w,s.Seconds),known,s.Seconds,courier:true,atlas:true);long delay=Math.Max(1,(path.LastOrDefault()?.EndAt??s.Seconds)-s.Seconds);long send=start+9-delay;Assert.True(send>=s.Seconds,"fixture must reach home before the last pre-rout inquiry window");At(s,send);Ask(s);At(s,Query(s).DueAt);Assert.True(Answer(s).Delivered);MoveAway(s);At(s,Answer(s).ReplyDueAt);var report=Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights);At(s,report.DueAt);var journey=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(s.Seconds,(journey.Route.LastOrDefault()?.EndAt??s.Seconds)+1));return s;}
    static TroopDispatch Original(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();
    static WorldSession MissedFailureReport(){var s=Failed(false);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single();MoveAway(s);At(s,r.ReplyDueAt);AtPersonEnd(s);return s;}
    static WorldSession FailedEvidence(bool evidence=true){var s=HomeReady();MoveAway(s);AtPersonEnd(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=NewGameMilitary.UnitCommandHoldingContract,TransportPolicy=evidence?NewGameMilitary.UnitSenderEvidenceContract:null},s.PlayerControl,s.Revision).Code);At(s,Original(s).DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    static UnitHeldOrderOutcome Late(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.CommandHolding!.Outcomes.Last();
    static void LateOriginal(WorldSession s){Send(s,NewMilitaryAction.DeliverHeldRecallHome);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);}
    static void LeaveAck(WorldSession s){var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+10000,home.Y)},s.PlayerControl,s.Revision).Code);At(s,Late(s).DueAt);At(s,Math.Max(s.Seconds,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Last().EndAt+1));Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,Late(s).ReplyMessage!,s.PlayerControl.Value));}
    [Theory][InlineData(true)][InlineData(false)]public void UnknownLateReceiptCannotChangeNewPolicyRetryAvailability(bool evidence){var s=FailedEvidence(evidence);Assert.True(NewGameMilitary.UnitRetryAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.RetryRecallHome));LateOriginal(s);var w=s.DiagnosticSnapshot();Assert.Single(w.Messaging.Receipts,r=>r.MessageId==Original(s).Message);Assert.False(MessageFlow.Knows(w.Messaging,Late(s).ReplyMessage!,w.PlayerControl.Value));Assert.Equal(evidence,NewGameMilitary.UnitRetryAllowed(w,NewMilitaryAction.RetryRecallHome));}
    [Fact]public void UnconfirmedPhysicalReceiptAllowsBoundedDuplicateWithOneEffect(){var s=FailedEvidence();LateOriginal(s);var receipt=s.DiagnosticSnapshot().Messaging.Receipts.Single(r=>r.MessageId==Original(s).Message);int orders=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.RetryRecallHome);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Single();At(s,d.DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(2,w.Messaging.Attempts.Count(a=>a.MessageId==Original(s).Message));Assert.Equal(receipt,w.Messaging.Receipts.Single(r=>r.MessageId==Original(s).Message));Assert.Equal(orders,w.NewMilitary!.Orders.Length);Assert.False(w.NewMilitary.UnitRetry!.Receipts.Single().Applied);}
    [Fact]public void ActualAcknowledgementStopsRetryWithoutGlobalTruthShortcut(){var s=FailedEvidence();LateOriginal(s);Assert.True(NewGameMilitary.UnitRetryAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.RetryRecallHome));At(s,Late(s).DueAt);Assert.True(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,Late(s).ReplyMessage!,s.PlayerControl.Value));Assert.False(NewGameMilitary.UnitRetryAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.RetryRecallHome));}
    [Fact]public void PhysicallyReceivedQuoteIsReceiptEvidenceWithoutOldAck(){var s=FailedEvidence();LateOriginal(s);LeaveAck(s);Assert.True(NewGameMilitary.UnitRetryAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.RetryRecallHome));Ask(s,NewMilitaryAction.InquireUnitHome);At(s,Query(s).DueAt);At(s,Answer(s).ReplyDueAt);Assert.True(Quote(s.DiagnosticSnapshot()).Originals.Single(x=>x.Original==Original(s).Message).Received);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,Late(s).ReplyMessage!,s.PlayerControl.Value));Assert.False(NewGameMilitary.UnitRetryAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.RetryRecallHome));}
    [Fact]public void UnknownReceiptNeverRemovesCopyLimit(){var s=FailedEvidence();LateOriginal(s);LeaveAck(s);for(int n=2;n<=3;n++){Send(s,NewMilitaryAction.RetryRecallKnown);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last();At(s,d.DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Receipts.Last().ReplyDueAt);}var w=s.DiagnosticSnapshot();Assert.Equal(3,w.Messaging.Attempts.Count(a=>a.MessageId==Original(s).Message));Assert.False(NewGameMilitary.UnitRetryAllowed(w,NewMilitaryAction.RetryRecallHome));Assert.Single(w.Messaging.Receipts,r=>r.MessageId==Original(s).Message);Assert.Single(w.NewMilitary!.Orders,o=>o.Id.Value.StartsWith("order:unit-post/"));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void SenderEvidenceAndDuplicateRestoreSameFuture(int phase){var s=FailedEvidence();Send(s,NewMilitaryAction.DeliverHeldRecallHome);long due=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt;if(phase>0)At(s,due);if(phase>1)Send(s,NewMilitaryAction.RetryRecallHome);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,c})At(x,due+30);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)]public void ForgedTransportPolicyIsRejected(int kind){var s=FailedEvidence();var w=s.DiagnosticSnapshot();if(kind==0){int n=Array.FindIndex(w.NewMilitary!.Requests,q=>q.Input.Action==NewMilitaryAction.RemoteRecall);var q=w.NewMilitary.Requests[n];w.NewMilitary.Requests[n]=q with{Input=q.Input with{TransportPolicy=null}};}else{int n=Array.FindIndex(w.Messaging.Messages,m=>m.Id==Original(s).Message);var m=w.Messaging.Messages[n];var body=ContractJson.Read<UnitPostOrder>(System.Text.Encoding.UTF8.GetBytes(m.Body));w.Messaging.Messages[n]=m with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(body with{TransportPolicy=null}))};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void UnknownPolicyIsRejectedAtomically(){var s=HomeReady();string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{TransportPolicy="unknown"},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void EvidencePolicyCannotExtendAuthoredDeadline(){var s=HomeReady();var w=s.DiagnosticSnapshot();var from=NewGameMilitary.PersonPosition(w,s.Seconds);var to=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(from,to,s.Seconds,courier:true,atlas:true);long due=Math.Max(s.Seconds+1,path.LastOrDefault()?.EndAt??0);var back=RegionalGround.Plan(to,from,due,courier:true,atlas:true);long until=Math.Max(due+1,back.LastOrDefault()?.EndAt??0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=NewGameMilitary.UnitCommandHoldingContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract,DeliverBy=until},s.PlayerControl,s.Revision).Code);At(s,until);Assert.False(NewGameMilitary.UnitRetryAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.RetryRecallHome));Assert.False(NewGameMilitary.HeldAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.DeliverHeldRecallHome));}
    [Fact]public void RemoteUnitDoesNotLearnReceiptFromWorldTruth(){var s=AtMissedReport();var r=Answer(s);Send(s,NewMilitaryAction.TakeHeldReply);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value));Assert.False(NewGameMilitary.ReceiptConfirmedToSender(w,r.ReplyMessage,NewGameMilitary.UnitIds[0].Value));Send(s,NewMilitaryAction.ReturnHeldReportHome);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);w=s.DiagnosticSnapshot();Assert.Equal(UnitReplyLeg.Retry,w.NewMilitary!.ReplyRecovery!.Flights.Last().Kind);Assert.Single(w.Messaging.Receipts,x=>x.MessageId==r.ReplyMessage);}
    [Fact]public void SenderPostWitnessesItsOwnLocalPhysicalHandover(){var s=AtHeldOriginal();var r=Answer(s);Send(s,NewMilitaryAction.TakeHeldReply);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.ReceiptConfirmedToSender(w,r.ReplyMessage,NewGameMilitary.UnitIds[0].Value));long until=s.Seconds+60;At(s,until);Assert.True(NewGameMilitary.ReceiptConfirmedToSender(s.DiagnosticSnapshot(),r.ReplyMessage,NewGameMilitary.UnitIds[0].Value));Assert.Equal(1,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Count(f=>f.Kind==UnitReplyLeg.Retry));}
    [Fact]public void HistoricalWitnessRemainsAfterUnitMovesAndSaveRestores(){var s=AtHeldOriginal();var r=Answer(s);Send(s,NewMilitaryAction.TakeHeldReply);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var t=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.Recall);At(s,ArmyEnd(s)+1);var w=s.DiagnosticSnapshot();Assert.True(RegionalGround.Distance(NewGameMilitary.Position(w,0,s.Seconds),t.Destination)>1000);Assert.True(NewGameMilitary.ReceiptConfirmedToSender(w,r.ReplyMessage,NewGameMilitary.UnitIds[0].Value));var c=new WorldSession(ContractJson.Copy(w));Assert.True(NewGameMilitary.ReceiptConfirmedToSender(c.DiagnosticSnapshot(),r.ReplyMessage,NewGameMilitary.UnitIds[0].Value));}
    [Fact]public void OldPolicyShapeRemainsOmitted(){var s=FailedEvidence(false);var w=s.DiagnosticSnapshot();var q=w.NewMilitary!.Requests.Single(q=>q.Input.Action==NewMilitaryAction.RemoteRecall);Assert.DoesNotContain("TransportPolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(q.Input)));Assert.DoesNotContain("TransportPolicy",w.Messaging.Messages.Single(m=>m.Id==Original(s).Message).Body);}
    [Fact]public void NewRetryPolicyCanAdoptEvidenceWithoutRewritingOldOriginal(){var s=FailedEvidence(false);LateOriginal(s);var w=s.DiagnosticSnapshot();var original=w.Messaging.Messages.Single(m=>m.Id==Original(s).Message);Assert.False(NewGameMilitary.UnitRetryAllowed(w,NewMilitaryAction.RetryRecallHome));Assert.True(NewGameMilitary.UnitRetryAllowed(w,NewMilitaryAction.RetryRecallHome,NewGameMilitary.UnitSenderEvidenceContract));Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RetryRecallHome) with{TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},s.PlayerControl,s.Revision).Code);Assert.Equal(original,s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==original.Id));var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));long until=s.Seconds+30;foreach(var x in new[]{s,c})At(x,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));Assert.Single(s.DiagnosticSnapshot().Messaging.Receipts,r=>r.MessageId==original.Id);}
    [Fact]public void PlayerWitnessUsesSamePhysicalHandoverRuleAsUnitSender(){var s=HomeReady();Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=NewGameMilitary.UnitCommandHoldingContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},s.PlayerControl,s.Revision).Code);At(s,Original(s).DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);LateOriginal(s);var w=s.DiagnosticSnapshot();Assert.False(MessageFlow.Knows(w.Messaging,Late(s).ReplyMessage!,w.PlayerControl.Value));Assert.True(NewGameMilitary.ReceiptConfirmedToSender(w,Original(s).Message,w.PlayerControl.Value));Assert.False(NewGameMilitary.UnitRetryAllowed(w,NewMilitaryAction.RetryRecallHome));var c=new WorldSession(ContractJson.Copy(w));Assert.True(NewGameMilitary.ReceiptConfirmedToSender(c.DiagnosticSnapshot(),Original(s).Message,c.PlayerControl.Value));}
}
